const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/compliance/contracts/%7Bcontract_id%7D/documents',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'status[]': ['not_compliant', 'in_review'],
    allow_vendor_submission: 'true'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/compliance/contracts/%7Bcontract_id%7D/documents?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&status%5B%5D=not_compliant&status%5B%5D=in_review&allow_vendor_submission=true"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

